"""Write the computed Step 4 report, preserving earlier research sections."""
from pathlib import Path
import json,time,datetime,re,importlib.util,sys
import numpy as np
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'data';S=ROOT/'scripts'
spec=importlib.util.spec_from_file_location('report_losses',S/'report_losses.py');mod=importlib.util.module_from_spec(spec);sys.modules['report_losses']=mod;spec.loader.exec_module(mod);md=mod.md

def read(n):return json.loads((D/n).read_text())
def pct(x):return f'{100*x:.2f}%'
def pp(x):return f'{100*x:+.2f} pp'
def main():
    started=time.time();decision=read('step4_decision.json');validation=read('step4_validation.json');retention=read('step4_retention.json');protocol=read('step4_protocol.json');train=read('step4_training_manifest.json');prep=read('step4_prepare_status.json');fit=read('step4_fit_status.json');assert validation['all_passed'];assert retention['kept']==decision['keep']
    metrics=pd.read_csv(D/'step4_metrics.csv');leads=pd.read_csv(D/'step4_lead_metrics.csv');cis=pd.read_csv(D/'step4_bootstrap_intervals.csv').set_index('metric');thresholds=pd.read_csv(D/'step4_operating_thresholds.csv');perasset=pd.read_csv(D/'step4_per_asset_metrics.csv');unions=pd.read_csv(D/'step4_fixed_union_increment.csv')
    primary=metrics[(metrics.cut_usd==1000)&(metrics.split=='holdout')&(metrics.source=='venue_only')].set_index('method');mainlead=leads[(leads.cut_usd==1000)&(leads.source=='venue_only')].set_index('method');model=primary.loc['model_5pct'];screen=primary.loc[decision['best_budget_screen']]
    methodnames={'model_5pct':'Model, 5% budget','act_5pct':'LTV screen, 5% budget','combined_5pct':'LTV-or-gap screen, 5% budget','act_fixed':'Fixed LTV >70%','combined_fixed':'Fixed LTV >70% or gap >2%','act_fixed_plus_model':'Fixed LTV + model alerts','combined_fixed_plus_model':'Fixed combined + model alerts'}
    def metric_table(frame):
        rows=[]
        for row in frame.itertuples():rows.append(dict(method=methodnames[row.method],hours=f'{row.hours:,}',alerts=f'{row.alerts:,}',alert_rate=pct(row.alert_fraction),AUC=f'{row.auc:.4f}' if pd.notna(row.auc) else 'undefined',precision=pct(row.precision),recall=pct(row.recall)))
        return md(pd.DataFrame(rows))
    def ci_format(name,unit='pct'):
        row=cis.loc[name];factor=100 if unit=='pct' else 1;tail='%' if unit=='pct' else 'h';return f"[{row.lower_95*factor:.2f}, {row.upper_95*factor:.2f}] {tail}"
    gate_rows=[dict(criterion='Recall gain >=5 pp AND no lower precision',observed=f"recall {pp(decision['recall_gain'])}; precision {pp(decision['precision_gain'])}",result='PASS' if decision['criteria']['recall_gain_5pp_and_no_lower_precision'] else 'FAIL'),dict(criterion='95% position-bootstrap recall-gain interval above zero',observed=f"[{100*decision['recall_gain_95ci'][0]:+.2f}, {100*decision['recall_gain_95ci'][1]:+.2f}] pp",result='PASS' if decision['criteria']['positive_95pct_position_bootstrap_recall_gain'] else 'FAIL'),dict(criterion='Median lead >=1h earlier than budget-matched act screen',observed=f"{decision['median_lead_gain_h']:+.2f}h",result='PASS' if decision['criteria']['median_lead_at_least_1h_earlier_than_act'] else 'FAIL')]
    text=['## Step 4 — risk model: '+decision['recommendation'].lower(),
    f"**Recommendation: {decision['recommendation']} this fitted risk model.** On the 2026 primary cohort, at the same 5% alert-hour budget, its recall is {pct(model.recall)} versus {pct(screen.recall)} for the best screen, and precision is {pct(model.precision)} versus {pct(screen.precision)}. It fails the required recall/precision improvement and the positive bootstrap-gain test. Its earlier warning at the matched budget does not override those failures. No hyperparameter or threshold retuning was performed after this comparison.",
    '### Frozen acceptance test',md(pd.DataFrame(gate_rows)),
    'Primary = at least $1,000 of collateral at episode start, venue-feed episodes only. Secondary = at least $100, evaluated with the **same** primary-trained model. Binance-fallback episodes enter sensitivity analyses only. Both screens are compared at the same 5% budget for keep/drop; their original fixed thresholds are reported separately. The accepted specification is recorded in `data/step4_protocol.json`, written before fitting. The keep/drop decision is `data/step4_decision.json`.',
    '### Primary holdout metrics',
    f"Rows: `data/step4_metrics.csv`, filtered to cut_usd=1000, split=holdout, source=venue_only. This is {int(model.hours):,} eligible position-hours, {int(model.positions):,} unique market/borrower positions, {int(model.episodes):,} replay episodes and {int(model.positive_hours):,} positive 24-hour labels. Each budget-matched method alerts on {int(model.alerts):,} hours. The two screen scores happen to select identical alerts in this cohort.",metric_table(primary.reset_index()),
    'AUC for the model and budget-matched screens uses their continuous ranking scores. The fixed-screen/union AUCs use binary predictions; those are different ROC summaries and are shown for completeness, not used in model selection. A slightly higher model AUC does not satisfy the required gain at the specified operating point.',
    '### What the model adds to the existing fixed screens',
    f"**Fixed combined screens alone: recall {pct(primary.loc['combined_fixed','recall'])}, precision {pct(primary.loc['combined_fixed','precision'])}; fixed combined screens plus the model’s alerts: recall {pct(primary.loc['combined_fixed_plus_model','recall'])}, precision {pct(primary.loc['combined_fixed_plus_model','precision'])}.** Added alerts: {int(unions[(unions.cut_usd==1000)&(unions.split=='holdout')&(unions.source=='venue_only')&(unions.fixed_screen=='combined_fixed')].new_alerts.iloc[0]):,}. The fixed act-only screen has the same result here. Every model alert is already covered by the fixed screens; the union adds no positive or negative hours. The fixed/union alert rate is {pct(primary.loc['combined_fixed','alert_fraction'])}, not 5%.",
    '### Bootstrap intervals on the primary holdout',
    f"Source: `data/step4_bootstrap_replicates.parquet` and `data/step4_bootstrap_intervals.csv`. {protocol['bootstrap']['replicates']:,} paired resamples draw {int(model.positions):,} positions with replacement; all hours and liquidation events belonging to a sampled position move together. The intervals are two-sided 95% percentiles. In each resample the recall comparator is the better of both budget-matched screens, not a favorable choice made afterward."]
    interval_rows=[]
    for name in primary.index:interval_rows.append(dict(method=methodnames[name],precision=pct(primary.loc[name,'precision']),precision_95=ci_format(name+'_precision'),recall=pct(primary.loc[name,'recall']),recall_95=ci_format(name+'_recall')))
    text.append(md(pd.DataFrame(interval_rows)))
    diff=pd.DataFrame([dict(difference='Recall: model minus best budget screen',estimate=pp(decision['recall_gain']),interval_95=f"[{100*cis.loc['recall_gain_vs_best','lower_95']:+.2f}, {100*cis.loc['recall_gain_vs_best','upper_95']:+.2f}] pp"),dict(difference='Precision: model minus best budget screen',estimate=pp(decision['precision_gain']),interval_95=f"[{100*cis.loc['precision_gain_vs_best','lower_95']:+.2f}, {100*cis.loc['precision_gain_vs_best','upper_95']:+.2f}] pp"),dict(difference='Median lead: model minus budget act screen',estimate=f"{decision['median_lead_gain_h']:+.2f}h",interval_95=ci_format('median_lead_gain_vs_act','hours'))]);text.append(md(diff))
    text+=['[ASSUMPTION] Bootstrap intervals are conditional on the fitted model and the original evaluation-set operating points: alert flags stay fixed while positions are resampled, so the alert fraction can vary within a replicate. No models are refitted or cutoffs reselected inside the bootstrap. This preserves whole-position dependence but does not capture common crash-day/market dependence or uncertainty from model selection. AUC is reported as a point estimate; the acceptance-test confidence interval is for recall gain, with precision and lead-time intervals also reported.',
    '### Lead-time comparison',
    'Rows: `data/step4_lead_metrics.csv`, same primary holdout filter; event-level evidence is `data/step4_primary_lead_events.parquet`. Lead is measured from the earliest eligible alert in the 24 hours before each observed liquidation. Missed events receive **zero hours**, so median lead uses the same event census for every method. The paired-detection result is reported separately. These are observed event warnings, not simulated policy saves.']
    lead_table=mainlead.reset_index()[['method','events','positions','detected_events','event_recall','median_lead_all_events_h','median_lead_detected_h']].copy();lead_table['method']=lead_table.method.map(methodnames);lead_table['event_recall']=lead_table.event_recall.map(pct);text.append(md(lead_table))
    text+= [f"The model’s median lead is {mainlead.loc['model_5pct','median_lead_all_events_h']:.2f}h versus {mainlead.loc['act_5pct','median_lead_all_events_h']:.2f}h for the budget-matched act screen: a {decision['median_lead_gain_h']:.2f}h improvement. Across {decision['paired_detected_events']:,} events detected by both, median paired improvement is {decision['paired_detected_median_gain_h']:.2f}h. The original fixed 70% act screen warns at a median {mainlead.loc['act_fixed','median_lead_all_events_h']:.2f}h within this capped window, earlier than the model. The model spreads its limited alerts across more liquidation events, but covers fewer positive hours and has lower precision; its alerts add no coverage to the fixed screens already running.",
    '[ASSUMPTION] Lead-time eligibility requires at least one valid, labeled pre-event hour within 24 hours. Repeated liquidations are separate events but are clustered by position in the bootstrap. Observation gaps and episode edges can shorten the available warning window; maximum observed lead and eligible-hour count are stored per event. Lead time is capped at 24 hours, so the fixed screens may actually have fired earlier than shown.',
    '### Secondary size cut and price-source sensitivities',
    'Rows: `data/step4_metrics.csv`; 2026 results below reuse the primary-trained model. Each displayed cohort/source subset gets its own 5% score-rank operating point. These are descriptive sensitivities and cannot overturn the primary keep/drop test. The source subsets overlap only in the explicitly labeled all-prices sensitivity. No fallback episode was used for training.']
    sens=metrics[(metrics.split=='holdout')&metrics.method.isin(['model_5pct','act_5pct','combined_5pct'])&~((metrics.cut_usd==1000)&(metrics.source=='venue_only'))][['cut_usd','source','method','hours','positions','positive_hours','auc','precision','recall']].copy();sens['method']=sens.method.map(methodnames);sens['precision']=sens.precision.map(pct);sens['recall']=sens.recall.map(pct);text.append(md(sens))
    text+=['### Per-asset primary holdout view',
    'Rows: `data/step4_per_asset_metrics.csv`; 2026, >=$1,000, venue-only. These use the **global primary-cohort** 5% budget and then split its results by asset; the threshold is not retuned independently per asset.']
    assets=perasset[(perasset.cut_usd==1000)&(perasset.split=='holdout')&(perasset.source=='venue_only')&perasset.method.isin(['model_5pct','act_5pct','combined_5pct'])][['method','asset_group','hours','positive_hours','alerts','alert_fraction','precision','recall']].copy();assets['method']=assets.method.map(methodnames)
    for c in ['alert_fraction','precision','recall']:assets[c]=assets[c].map(pct)
    text.append(md(assets))
    text+=['### Training, features and operating points',
    f"One `HistGradientBoostingClassifier` ({protocol['versions']['scikit-learn']}) was fitted to {train['train_rows']:,} pre-2026 primary/venue-only hours from {train['train_episodes']:,} episodes and {train['train_positions']:,} positions, including {train['train_positives']:,} positive hours. It uses {protocol['parameters']['max_iter']} boosting iterations, learning rate {protocol['parameters']['learning_rate']}, at most {protocol['parameters']['max_leaf_nodes']} leaves per tree, depth {protocol['parameters']['max_depth']}, minimum leaf size {protocol['parameters']['min_samples_leaf']}, L2 regularization {protocol['parameters']['l2_regularization']}, {protocol['parameters']['max_bins']} histogram bins, and seed {protocol['parameters']['random_state']}. Early stopping and class reweighting are disabled. There is no hyperparameter search, random train/holdout mixing, or holdout-based refit. Each hour has equal training weight.",
    'Feature order, unchanged from Step 2: `'+ '`, `'.join(protocol['features'])+'`. Neither outcomes, borrower IDs, future owner actions, episode size membership nor oracle-source flags are model inputs. Training labels and their full 24-hour windows end before 1 January 2026; holdout rows start in 2026. The model predicts observed borrower liquidation, not the residual liquidation risk after DEFAULT policy intervention.',
    '[ASSUMPTION] Cohort membership uses the episode’s observed start collateral value; only hours from that start through the existing episode end are used. This avoids applying a future start balance to earlier pulled history. All eligible hours are considered, including hours where no screen fires and hours after a position closes; the screen-filtered retrieval table is not the training data. The eligible Step 2 episode definition retains its full-window missing-state/reconstruction exclusions. The same position may appear in disjoint episodes on both sides of the calendar split, but identifiers are not predictors.',
    f"No state or feature values are imputed. Unknown 24-hour labels exclude {prep['unknown_label_excluded']:,} otherwise in-window hours. Among the {prep['retained_hours']:,} retained >=$100 hours, {prep['rows_with_native_nan_features']:,} have undefined feature values (for example, LTV after collateral becomes zero); the estimator’s native missing-value routing handles them. Missing position-state hours are never supplied to fitting/evaluation. See the [official estimator documentation](https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.HistGradientBoostingClassifier.html) for native missing-value support.",
    '[ASSUMPTION] A replay episode containing any Binance-fallback span is assigned wholly to sensitivity, even if a particular hour has a valid venue feed. This conservatively keeps the source convention consistent with the size-stratified Step 2 tables. The hourly feature oracle remains the pulled Morpho value, unchanged. Source flags indicate replay-reconstruction coverage; they are not a substitute price inserted into features. The small Ethereum cohorts and accepted wstETH parity/exchange-rate assumptions remain labeled; Aave and all hours of the 13 failed-reconstruction positions remain excluded.',
    'Budget matching is deterministic and uses scores, not outcome labels: rank by model probability, by LTV for the act screen, and by `max(LTV / 0.70, oracle_gap_percent / 2)` for the combined screen. Sweeping the combined score scales both original boundaries by the same factor. Select `floor(0.05 × eligible_hours)` rows; a deterministic row-key hash breaks exact cutoff ties. Null screen inputs receive the lowest ranking score and never satisfy their fixed condition. This changes no feature value used by the model.',
    '[ASSUMPTION] These are retrospective precision/recall-at-5%-budget metrics: each evaluation set’s score distribution determines its own cutoff without looking at labels. They do not establish that a frozen deployment threshold would continue firing on exactly 5% of future hours. The model’s probability is not calibrated to all live loans: the dataset is event-enriched, uses the selected market universe, and the holdout has already been inspected for descriptive analyses in earlier steps.',
    'Primary holdout operating points from `data/step4_operating_thresholds.csv`:']
    text.append(md(thresholds[(thresholds.cut_usd==1000)&(thresholds.split=='holdout')&(thresholds.source=='venue_only')][['method','score_threshold','ltv_threshold','oracle_gap_pct_threshold','alerts','hours','ties_at_threshold']]))
    text+=['Pre-2026 primary-cohort metrics below are **in-sample diagnostics**, not an additional test set. They were not used to choose another model:',metric_table(metrics[(metrics.cut_usd==1000)&(metrics.split=='train')&(metrics.source=='venue_only')&metrics.method.isin(['model_5pct','act_5pct','combined_5pct'])]),
    '### Counts, validation, timing and failures',
    'Counts from `data/step4_prepare_status.json`, `data/step4_hour_counts.csv` and `data/step4_validation.json`:']
    text.append(md(pd.DataFrame([dict(measure=k,count=prep[k]) for k in ['input_hours','within_cohort_episode_hours','missing_state_excluded','unknown_label_excluded','training_horizon_crossing_excluded','infinite_feature_excluded','retained_hours','rows_with_native_nan_features']])))
    text.append(md(pd.read_csv(D/'step4_hour_counts.csv').drop(columns=['missing_owner_action_feature_hours'])))
    text+= [f"Validation passed on all {validation['hours_checked']:,} retained hours: unique keys, episode/cohort bounds, temporal split, label masks, failed-position exclusions and source flags. All {validation['observed_labels_recomputed']:,} labels were independently recomputed from observed events. {validation['serialized_model_predictions_checked']:,} sampled predictions matched the serialized candidate. Full primary rankings and confusion counts matched independent calculations; the first {validation['bootstrap_draws_expanded']} position-bootstrap draws were explicitly expanded to reproduce hour metrics and event medians. All {validation['size_headlines_reconciled']} size/source headline rows reconcile to the original DEFAULT replay results. All bootstrap intervals and the keep/drop rules were recomputed. Records: `data/step4_validation.json`."]
    times=[]
    for file,label in [('step4_size_status.json','Step 2 size tables'),('step4_prepare_status.json','Episode-hour preparation and frozen protocol'),('step4_train_status.json','Classifier fit plus scoring'),('step4_evaluate_status.json','Evaluation including all sensitivities and bootstrap'),('step4_validation.json','Independent validation')]:times.append(dict(task=label,seconds=read(file)['elapsed_s']))
    text.append(md(pd.DataFrame(times)));wall=time.time()-read('step4_size_status.json')['started_at'];ts=read('step4_train_status.json');ev=read('step4_evaluate_status.json')
    text+= [f"Within those totals, fitting took {ts['fit_s']:.3f}s, scoring {ts['predict_s']:.3f}s and the {protocol['bootstrap']['replicates']:,}-replicate bootstrap {ev['bootstrap_s']:.3f}s. Recorded wall span from the successful size-table run to this report is {wall:.3f}s ({wall/60:.2f} minutes), including implementation/reporting gaps; initial reading and package installation preceded that timer. No liquidation or price source was re-downloaded. Free package wheels are cached in `data/raw/step4_wheels/`; dependency versions are pinned in `scripts/requirements_step4.txt`.",
    'Execution failures: the first size-exclusion partition check exposed the 151 zero-balance episodes with undefined oracle-derived value; assigning their observed zero collateral its known $0 value resolved it without imputing a price. No fitting, scoring or final validation failure remains. The **statistical acceptance failure is the result**: recall and precision are lower at the matched budget, and the recall-gain confidence interval is negative. Earlier budget-matched warning passes its gate but does not rescue the model.',
    '### Model retention and exact reproduction']
    if retention['kept']:text.append(f"Retained single-file bundle: `{retention['path']}`, **{retention['bytes']:,} bytes**, containing the estimator, ordered feature list, frozen protocol and training manifest. SHA-256: `{retention['sha256']}`.")
    else:text.append(f"**No trained model is retained.** The evaluated compressed candidate was {retention['evaluated_candidate_bytes']:,} bytes; `scripts/step4_finalize.py` removed it after validation because it failed the acceptance test. Predictions, operating points, bootstrap draws, manifests and all reports remain reproducible. `data/step4_retention.json` records this decision.")
    text+=['Exact training command, from this folder, using the existing local environment:','```sh\nscripts/.venv/bin/python3 -I scripts/step4_train.py\n```',
    'The fit command consumes `data/step4_hours.parquet` and the frozen protocol and creates an evaluation candidate. The full sequence below reproduces the size tables, preparation, fit, evaluation, validation and conditional retention. The report commands replace their generated sections, so run them in this order. All work stays in this research folder; Python uses `-I`.',
    '```sh\n# Only if the local environment needs the already-cached classifier dependency:\nscripts/.venv/bin/python3 -I -m pip install --no-index --find-links data/raw/step4_wheels scikit-learn=='+protocol['versions']['scikit-learn']+'\nscripts/.venv/bin/python3 -I scripts/step4_size_tables.py\nscripts/.venv/bin/python3 -I scripts/step4_prepare.py\nscripts/.venv/bin/python3 -I scripts/step4_train.py\nscripts/.venv/bin/python3 -I scripts/step4_evaluate.py\nscripts/.venv/bin/python3 -I scripts/validate_step4.py\nscripts/.venv/bin/python3 -I scripts/step4_finalize.py\nscripts/.venv/bin/python3 -I scripts/report_step4.py\n```',
    'The judge-facing evidence to cite is **“Step 2 by position size”** above for corridor replay performance and this section for the model rejection. This task does not edit the judges’ README, change product decisions, train an LLM, or run Step 5. **Stopped after Step 4. No commits.**']
    s=(ROOT/'README.md').read_text().split('\n## Step 4 — risk model:')[0];s=s.replace('# Liquidation dataset — Steps 1, 2 and 3','# Liquidation dataset — Steps 1–4');s=s.replace('Steps 2 and 3 are complete; stop before Step 4.','Steps 2–4 are complete; stopped after Step 4.');s=s.replace('No Step 4 model or Step 5 judge call has been run.','At the Step 3 stop, no Step 4 model or Step 5 judge call had been run.');s=s.replace('No Step 4 work has started. **Stopped after Step 3.**','Step 3 was completed before the separately authorized Step 4 analysis below.')
    a=s.index('\n## Decisions before Step 4') if '\n## Decisions before Step 4' in s else s.index('\n## Step 4 decisions accepted');b=s.index('\n## Step 2 by position size',a)
    accepted='\n## Step 4 decisions accepted\n\nThe founder specified >=$1,000 start collateral as primary, >=$100 as secondary, and fallback-only sensitivity; required >=5 percentage points of recall gain at no lower precision with a positive 95% position-bootstrap interval and >=1h earlier median warning. Keep/drop uses a matched 5% alert budget, with original fixed screens and their union with model alerts also reported.\n'
    text.insert(text.index('### Model retention and exact reproduction'),'Report generation initially received an unrendered metric table; rendering it as Markdown resolved the formatting error without changing any results.')
    s=s[:a]+accepted+s[b:];s=re.sub(r'Generated [^\n]+','Generated '+datetime.datetime.now(datetime.timezone.utc).isoformat()+'.',s,count=1);(ROOT/'README.md').write_text(s.rstrip()+'\n\n'+'\n\n'.join(text)+'\n')
    pd.DataFrame(times).to_csv(D/'step4_source_times.csv',index=False);(D/'step4_report_status.json').write_text(json.dumps(dict(status='complete',recommendation=decision['recommendation'],elapsed_s=time.time()-started,wall_span_from_size_tables_s=wall,completed_at=time.time()),indent=2)+'\n');print(json.dumps(dict(recommendation=decision['recommendation'],wall_span_s=wall,report_s=time.time()-started),indent=2))
if __name__=='__main__':main()
